1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8	
9		"github.com/entireio/cli/cmd/entire/cli/agent"
10		"github.com/entireio/cli/cmd/entire/cli/agent/external"
11		"github.com/entireio/cli/cmd/entire/cli/agent/types"
12		"github.com/entireio/cli/cmd/entire/cli/interactive"
13		"github.com/entireio/cli/cmd/entire/cli/logging"
14		"github.com/entireio/cli/cmd/entire/cli/paths"
15		"github.com/entireio/cli/cmd/entire/cli/settings"
16		"github.com/entireio/cli/cmd/entire/cli/summarize"
17	
18		"charm.land/huh/v2"
19	)
20	
21	var (
22		loadSummarySettings            = LoadEntireSettings
23		loadSummarySettingsFromFile    = settings.LoadFromFile
24		saveLocalSummarySettings       = SaveEntireSettingsLocal
25		getSummaryAgent                = agent.Get
26		listRegisteredAgents           = agent.List
27		isSummaryCLIAvailable          = agent.IsSummaryCLIAvailable
28		discoverSummaryProviders       = external.DiscoverAndRegister
29		discoverSummaryProvidersAlways = external.DiscoverAndRegisterAlways
30	)
31	
32	type checkpointSummaryProvider struct {
33		Name        types.AgentName
34		DisplayName string
35		Model       string
36		Generator   summarize.Generator
37	}
38	
39	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
40		s, err := loadSummarySettings(ctx)
41		if err != nil {
42			return nil, fmt.Errorf("loading settings: %w", err)
43		}
44	
45		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
46			providerName := types.AgentName(s.SummaryGeneration.Provider)
47			discoverSummaryProviderIfMissing(ctx, providerName)
48			if err := ensureSummaryProviderPresent(ctx, providerName); err != nil {
49				return nil, err
50			}
51			return buildCheckpointSummaryProvider(providerName, s.SummaryGeneration.Model)
52		}
53	
54		// Use the always-variant so installed external plugins surface in the
55		// picker even when external_agents is currently off. Installation
56		// (placing entire-agent-* on $PATH) is the user's opt-in to "this
57		// plugin exists"; selecting it in the picker is when external_agents
58		// flips on (handled by persistSummaryProviderSelection).
59		discoverSummaryProvidersAlways(ctx)
60		candidates := listEnabledSummaryProviders(ctx)
61	
62		switch len(candidates) {
63		case 0:
64			return nil, errors.New("no summary-capable provider is available; install claude, codex, gemini, cursor, or copilot, install an external entire-agent-* plugin that declares text_generator, or set summary_generation.provider in settings")
65		case 1:
66			return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: single installed provider")
67		default:
68			if !interactive.CanPromptInteractively() {
69				return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: first detected of multiple")
70			}
71	
72			selected, err := promptForSummaryProvider(candidates)
73			if err != nil {
74				return nil, err
75			}
76			provider, err := autoSelectSummaryProvider(ctx, w, selected, "interactive prompt selection")
77			if err != nil {
78				return nil, err
79			}
80			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
81			return provider, nil
82		}
83	}
84	
85	func discoverSummaryProviderIfMissing(ctx context.Context, name types.AgentName) {
86		if _, err := getSummaryAgent(name); err == nil {
87			return
88		}
89		discoverSummaryProvidersAlways(ctx)
90	}
91	
92	// autoSelectSummaryProvider builds a provider for an auto-selected candidate
93	// (single-installed or non-interactive-first-of-many) and persists the choice
94	// so subsequent runs don't re-decide. Persistence failure is surfaced as a
95	// warning — not an error — because the selection is still usable in-process.
96	func autoSelectSummaryProvider(ctx context.Context, w io.Writer, name types.AgentName, reason string) (*checkpointSummaryProvider, error) {
97		logging.Info(ctx, reason, "provider", string(name))
98		provider, err := buildCheckpointSummaryProvider(name, "")
99		if err != nil {
100			return nil, err
101		}
102		flagFlipped, saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model)
103		if saveErr != nil {
104			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
105				"error", saveErr.Error())
106			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
107		}
108		if flagFlipped {
109			fmt.Fprintln(w, externalAgentsAutoEnabledNotice)
110		}
111		return provider, nil
112	}
113	
114	func listEnabledSummaryProviders(_ context.Context) []checkpointSummaryProvider {
115		registered := listRegisteredAgents()
116		providers := make([]checkpointSummaryProvider, 0, len(registered))
117		for _, name := range registered {
118			ag, err := getSummaryAgent(name)
119			if err != nil {
120				continue
121			}
122			if _, ok := agent.AsTextGenerator(ag); !ok {
123				continue
124			}
125			// Check CLI binary on PATH for built-ins. External agents are already
126			// proven executable by discovery and are gated by text_generator.
127			if !isSummaryProviderAvailable(name, ag) {
128				continue
129			}
130			providers = append(providers, checkpointSummaryProvider{
131				Name:        name,
132				DisplayName: string(ag.Type()),
133			})
134		}
135		return providers
136	}
137	
138	func isSummaryProviderAvailable(name types.AgentName, ag agent.Agent) bool {
139		if external.IsExternal(ag) {
140			_, ok := agent.AsTextGenerator(ag)
141			return ok
142		}
143		return isSummaryCLIAvailable(name)
144	}
145	
146	func promptForSummaryProvider(providers []checkpointSummaryProvider) (types.AgentName, error) {
147		options := make([]huh.Option[string], 0, len(providers))
148		for _, provider := range providers {
149			options = append(options, huh.NewOption(provider.DisplayName, string(provider.Name)))
150		}
151	
152		var selected string
153		form := NewAccessibleForm(
154			huh.NewGroup(
155				huh.NewSelect[string]().
156					Title("Choose a summary provider").
157					Description("This choice will be saved. Use `entire configure --summarize-provider <name>` to change it later.").
158					Options(options...).
159					Value(&selected),
160			),
161		)
162		if err := form.Run(); err != nil {
163			return "", fmt.Errorf("summary provider selection cancelled: %w", err)
164		}
165	
166		return types.AgentName(selected), nil
167	}
168	
169	func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
170		ag, err := getSummaryAgent(name)
171		if err != nil {
172			return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
173		}
174	
175		textGenerator, ok := agent.AsTextGenerator(ag)
176		if !ok {
177			return nil, fmt.Errorf("agent %s does not support summary generation", name)
178		}
179	
180		effectiveModel := summarize.ResolveModel(name, model)
181	
182		return &checkpointSummaryProvider{
183			Name:        name,
184			DisplayName: string(ag.Type()),
185			Model:       effectiveModel,
186			Generator: &summarize.TextGeneratorAdapter{
187				TextGenerator: textGenerator,
188				Model:         effectiveModel,
189			},
190		}, nil
191	}
192	
193	// ensureSummaryProviderPresent returns an error if the named summary provider's
194	// CLI binary is not on PATH. Checks the binary directly (via exec.LookPath)
195	// rather than DetectPresence, because DetectPresence checks repo-level agent
196	// configuration — a repo using Claude Code for development can still use Codex
197	// or Gemini for summary generation as long as the binary is installed.
198	func ensureSummaryProviderPresent(_ context.Context, name types.AgentName) error {
199		ag, err := getSummaryAgent(name)
200		if err != nil {
201			return fmt.Errorf("unknown summary provider %s: %w", name, err)
202		}
203		if _, ok := agent.AsTextGenerator(ag); !ok {
204			return fmt.Errorf("agent %s does not support summary generation", name)
205		}
206		if !isSummaryProviderAvailable(name, ag) {
207			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or update summary_generation.provider in settings", name)
208		}
209		return nil
210	}
211	
212	func validateSummaryProvider(provider string) error {
213		name := types.AgentName(provider)
214		ag, err := getSummaryAgent(name)
215		if err != nil {
216			return fmt.Errorf("unknown summary provider %q: %w", provider, err)
217		}
218		if _, ok := agent.AsTextGenerator(ag); !ok {
219			return fmt.Errorf("agent %q does not support summary generation", provider)
220		}
221		if !isSummaryProviderAvailable(name, ag) {
222			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or choose another provider", provider)
223		}
224		return nil
225	}
226	
227	// persistSummaryProviderSelection writes the chosen provider to
228	// settings.local.json. When the chosen provider is an external agent and
229	// external_agents is not yet enabled, it also flips that setting on so the
230	// plugin can actually run; in that case it returns flagFlipped=true so the
231	// caller can surface a one-time notice. The flag is written to local because
232	// the provider choice is already machine-specific (depends on $PATH).
233	func persistSummaryProviderSelection(ctx context.Context, provider types.AgentName, model string) (flagFlipped bool, err error) {
234		targetFileAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
235		if err != nil {
236			targetFileAbs = settings.EntireSettingsLocalFile
237		}
238	
239		s, err := loadSummarySettingsFromFile(targetFileAbs)
240		if err != nil {
241			return false, fmt.Errorf("loading settings for update: %w", err)
242		}
243		if s.SummaryGeneration == nil {
244			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
245		}
246		s.SummaryGeneration.SetProvider(string(provider), model)
247	
248		if ag, getErr := getSummaryAgent(provider); getErr == nil && external.IsExternal(ag) && !s.ExternalAgents {
249			s.ExternalAgents = true
250			flagFlipped = true
251		}
252	
253		if err := saveLocalSummarySettings(ctx, s); err != nil {
