package cli

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// parseTuneOutput extracts the runner-id -> new-template map the tuning model
// is instructed to emit as a single JSON object. The model may wrap the object
// in prose or code fences, so we slice from the first "{" to the last "}".
func parseTuneOutput(text string) (map[string]string, error) {
	obj := extractJSONObject(text)
	if obj == "" {
		return nil, errors.New("no JSON object found in model output")
	}
	var m map[string]string
	if err := json.Unmarshal([]byte(obj), &m); err != nil {
		return nil, fmt.Errorf("parse model output as {runner: template}: %w", err)
	}
	if len(m) == 0 {
		return nil, errors.New("model returned an empty object (no templates to apply)")
	}
	return m, nil
}

// extractJSONObject returns the outermost {...} span in text, after stripping
// any surrounding markdown code fences. Returns "" when none is found.
func extractJSONObject(text string) string {
	text = stripCodeFences(strings.TrimSpace(text))
	start := strings.Index(text, "{")
	end := strings.LastIndex(text, "}")
	if start < 0 || end <= start {
		return ""
	}
	return text[start : end+1]
}

func stripCodeFences(text string) string {
	if !strings.HasPrefix(text, "```") {
		return text
	}
	// Drop the opening fence line (``` or ```json) and the closing fence.
	if nl := strings.IndexByte(text, '\n'); nl >= 0 {
		text = text[nl+1:]
	}
	if i := strings.LastIndex(text, "```"); i >= 0 {
		text = text[:i]
	}
	return strings.TrimSpace(text)
}

// replaceRunnerTemplate swaps only the prompt.template value inside a runner
// JSON document, leaving every other field and the file's formatting
// byte-for-byte intact. It works on the raw bytes (not a re-marshal) so unknown
// or backend-managed fields are never dropped and the git diff stays scoped to
// the prompt change. Returns the original bytes unchanged when newTemplate
// matches the current template.
func replaceRunnerTemplate(raw []byte, newTemplate string) ([]byte, error) {
	var top map[string]json.RawMessage
	if err := json.Unmarshal(raw, &top); err != nil {
		return nil, fmt.Errorf("parse runner JSON: %w", err)
	}
	promptRaw, ok := top["prompt"]
	if !ok {
		return nil, errors.New("runner has no \"prompt\" object")
	}
	var promptObj map[string]json.RawMessage
	if err := json.Unmarshal(promptRaw, &promptObj); err != nil {
		return nil, fmt.Errorf("parse runner prompt object: %w", err)
	}
	// oldVal holds the original on-disk bytes of the template value, so it is a
	// guaranteed substring of raw.
	oldVal, ok := promptObj["template"]
	if !ok {
		return nil, errors.New("runner has no \"prompt.template\" field")
	}

	newVal, err := encodeJSONString(newTemplate)
	if err != nil {
		return nil, err
	}
	if bytes.Equal(oldVal, newVal) {
		return raw, nil
	}

	if n := bytes.Count(raw, oldVal); n != 1 {
		return nil, fmt.Errorf("expected exactly one occurrence of the current template, found %d", n)
	}
	out := bytes.Replace(raw, oldVal, newVal, 1)
	if !json.Valid(out) {
		return nil, errors.New("template replacement produced invalid JSON")
	}
	return out, nil
}

// encodeJSONString encodes s as a JSON string without HTML escaping, so
// characters like <, >, and & stay literal — matching the style the runner
// files are authored in and keeping diffs minimal.
func encodeJSONString(s string) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return nil, fmt.Errorf("encode template string: %w", err)
	}
	return bytes.TrimRight(buf.Bytes(), "\n"), nil
}

package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// tuneRunner is one .entire/runners/*.json file loaded for tuning. Raw holds
// the verbatim file bytes (used for surgical template replacement); Template is
// the current prompt.template extracted for display in the prompt.
type tuneRunner struct {
	ID       string
	Path     string
	Raw      []byte
	Template string
}

// loadTuneRunners reads the runner configs under <repoRoot>/.entire/runners.
// When filter is non-empty it keeps only the runner whose id matches (with or
// without the "trail-" prefix). Returns an error when the directory is missing
// or the filter matches nothing.
func loadTuneRunners(repoRoot, filter string) ([]tuneRunner, error) {
	dir := filepath.Join(repoRoot, ".entire", "runners")
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("reading %s: %w", dir, err)
	}

	var runners []tuneRunner
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		path := filepath.Join(dir, e.Name())
		raw, err := os.ReadFile(path) //nolint:gosec // path is derived from repo root + dir listing
		if err != nil {
			return nil, fmt.Errorf("reading %s: %w", path, err)
		}
		var doc struct {
			ID     string `json:"id"`
			Prompt struct {
				Template string `json:"template"`
			} `json:"prompt"`
		}
		if err := json.Unmarshal(raw, &doc); err != nil {
			return nil, fmt.Errorf("parsing %s: %w", path, err)
		}
		if doc.ID == "" {
			doc.ID = strings.TrimSuffix(e.Name(), ".json")
		}
		runners = append(runners, tuneRunner{
			ID:       doc.ID,
			Path:     path,
			Raw:      raw,
			Template: doc.Prompt.Template,
		})
	}

	if filter != "" {
		want := normalizeRunnerID(filter)
		filtered := runners[:0]
		for _, r := range runners {
			if normalizeRunnerID(r.ID) == want {
				filtered = append(filtered, r)
			}
		}
		runners = filtered
		if len(runners) == 0 {
			return nil, fmt.Errorf("no runner matching %q under %s", filter, dir)
		}
	}

	if len(runners) == 0 {
		return nil, fmt.Errorf("no runner configs found under %s", dir)
	}
	sort.Slice(runners, func(i, j int) bool { return runners[i].ID < runners[j].ID })
	return runners, nil
}

func normalizeRunnerID(id string) string {
	return strings.TrimPrefix(strings.TrimSpace(id), "trail-")
}

// buildTunePrompt assembles the full instruction prompt: what to do, the
// gathered repo signal, and the current runner templates. The model is told to
// return a single JSON object mapping runner id -> rewritten template, which
// parseTuneOutput consumes.
func buildTunePrompt(brief string, runners []tuneRunner) string {
	var b strings.Builder

	b.WriteString(`You are tuning Entire "trail" runner prompts so their risk/quality evaluations fit THIS specific repository instead of the generic defaults they shipped with.

Each runner below is a JSON config with a prompt.template that instructs an evaluator (e.g. risk, confidence, drift) how to score a branch's changes. The shipped templates are written for a generic web/backend app. Your job is to rewrite each template so its dimensions and score bands reflect what actually matters in this repo, using the gathered signal below.

Guidelines:
- Keep the template's overall shape: the role line, the context-gathering steps, the scored dimensions, the score bands, and the final "output ONLY this JSON object" contract. Preserve every {{placeholder}} (e.g. {{branch}}, {{base_branch}}, {{previous_findings}}) exactly.
- Re-weight and reword the dimensions toward this repo's real risk/quality surface. Drop dimensions that don't apply here; add ones that do.
- Re-anchor the score bands to concrete things in THIS repo, informed by the empirical signal (incident themes, hot files, past findings) where present.
- Be concise. Do not turn a tight template into an essay.
- Only include a runner in your output if you are changing it.

`)

	b.WriteString("## Gathered repository signal\n\n")
	b.WriteString(strings.TrimSpace(brief))
	b.WriteString("\n\n")

	b.WriteString("## Current runner templates\n\n")
	for _, r := range runners {
		fmt.Fprintf(&b, "### %s\n\n", r.ID)
		b.WriteString("```\n")
		b.WriteString(r.Template)
		b.WriteString("\n```\n\n")
	}

	b.WriteString(`## Output

Return ONLY a single JSON object mapping each changed runner's id to its full rewritten prompt.template string. No prose, no markdown fences. Example shape:

{"trail-risk": "<full rewritten template text>", "trail-confidence": "<full rewritten template text>"}

Omit any runner you are not changing.`)

	return b.String()
}

package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

const (
	tuneDocCap             = 6000 // max chars embedded per doc (CLAUDE.md etc.)
	tuneReadmeCap          = 2000
	tuneTopFiles           = 15 // hottest files to surface from checkpoints
	tuneMaxTrails+Findings = 8  // trails to pull findings from in the trails tier
)

// tuneSources selects which data tiers gatherTuningContext collects.
type tuneSources struct {
	repo        bool
	prs         bool
	checkpoints bool
	trails      bool
}

func allTuneSources() tuneSources {
	return tuneSources{repo: true, prs: true, checkpoints: true, trails: true}
}

func parseTuneSources(list []string) (tuneSources, error) {
	if len(list) == 0 {
		return allTuneSources(), nil
	}
	var s tuneSources
	for _, item := range list {
		switch strings.ToLower(strings.TrimSpace(item)) {
		case "":
			continue
		case "all":
			return allTuneSources(), nil
		case "repo":
			s.repo = true
		case "pr", "prs", "issue", "issues":
			s.prs = true
		case "checkpoint", "checkpoints":
			s.checkpoints = true
		case "trail", "trails":
			s.trails = true
		default:
			return s, fmt.Errorf("unknown source %q (valid: repo, prs, checkpoints, trails, all)", item)
		}
	}
	return s, nil
}

// gatherTuningContext builds the markdown "tuning brief" from the selected
// tiers. Every tier is best-effort: a tier that is unavailable (no gh, no
// checkpoints, trails not enabled) records a one-line skip note instead of
// failing the command.
func gatherTuningContext(ctx context.Context, errW io.Writer, repoRoot string, src tuneSources, limit int) string {
	var b strings.Builder

	if src.repo {
		b.WriteString("### Repository (static)\n\n")
		b.WriteString(gatherRepoStatics(repoRoot))
		b.WriteString("\n")
	}
	if src.prs {
		b.WriteString("### Merged PRs & issues\n\n")
		b.WriteString(gatherPRsAndIssues(ctx, limit))
		b.WriteString("\n")
	}
	if src.checkpoints {
		b.WriteString("### Checkpoint history (what changes look like here)\n\n")
		b.WriteString(gatherCheckpoints(ctx, limit))
		b.WriteString("\n")
	}
	if src.trails {
		b.WriteString("### Trail history & past findings (eval feedback loop)\n\n")
		b.WriteString(gatherTrails(ctx, errW, limit))
		b.WriteString("\n")
	}

	return b.String()
}

func skip(reason string) string { return "_skipped: " + reason + "_\n" }

func gatherRepoStatics(repoRoot string) string {
	var b strings.Builder

	if mod, ok := readCapped(filepath.Join(repoRoot, "go.mod"), 400); ok {
		for _, line := range strings.Split(mod, "\n") {
			line = strings.TrimSpace(line)
			if strings.HasPrefix(line, "module ") || strings.HasPrefix(line, "go ") {
				fmt.Fprintf(&b, "- %s\n", line)
			}
		}
	}

	if entries, err := os.ReadDir(repoRoot); err == nil {
		var dirs []string
		for _, e := range entries {
			if e.IsDir() && !strings.HasPrefix(e.Name(), ".") {
				dirs = append(dirs, e.Name())
			}
		}
		if len(dirs) > 0 {
			fmt.Fprintf(&b, "- Top-level dirs: %s\n", strings.Join(dirs, ", "))
		}
	}
	b.WriteString("\n")

	for _, doc := range []struct {
		name string
		cap  int
	}{
		{"CLAUDE.md", tuneDocCap},
		{"AGENTS.md", tuneDocCap},
		{"README.md", tuneReadmeCap},
	} {
		text, ok := readCapped(filepath.Join(repoRoot, doc.name), doc.cap)
		if !ok || strings.TrimSpace(text) == "" {
			continue
		}
		fmt.Fprintf(&b, "#### %s\n\n", doc.name)
		b.WriteString(text)
		b.WriteString("\n\n")
	}

	if b.Len() == 0 {
		return skip("no go.mod, CLAUDE.md, AGENTS.md, or README.md found")
	}
	return b.String()
}

// readCapped reads a file and truncates it to max characters, appending a
// truncation marker when cut. Returns ok=false when the file can't be read.
func readCapped(path string, max int) (string, bool) {
	data, err := os.ReadFile(path) //nolint:gosec // caller passes repo-root-relative paths
	if err != nil {
		return "", false
	}
	s := string(data)
	if len(s) > max {
		s = s[:max] + "\n…(truncated)…"
	}
	return s, true
}

func gatherPRsAndIssues(ctx context.Context, limit int) string {
	if _, err := exec.LookPath("gh"); err != nil {
		return skip("gh CLI not on PATH")
	}
	var b strings.Builder

	prs, err := runGHList(ctx, "pr", "--state", "merged", "--limit", itoa(limit),
		"--json", "number,title,labels")
	if err != nil {
		b.WriteString(skip("gh pr list failed: " + oneLine(err.Error())))
	} else if len(prs) == 0 {
		b.WriteString("No merged PRs found.\n")
	} else {
		b.WriteString("Recent merged PRs:\n")
		for _, p := range prs {
			fmt.Fprintf(&b, "- #%d %s%s\n", p.Number, oneLine(p.Title), labelSuffix(p.Labels))
		}
	}

	issues, err := runGHList(ctx, "issue", "--state", "all", "--limit", itoa(limit),
		"--json", "number,title,labels")
	if err != nil {
		b.WriteString(skip("gh issue list failed: " + oneLine(err.Error())))
	} else if len(issues) > 0 {
		b.WriteString("\nRecent issues:\n")
		for _, p := range issues {
			fmt.Fprintf(&b, "- #%d %s%s\n", p.Number, oneLine(p.Title), labelSuffix(p.Labels))
		}
	}

	return b.String()
}

type ghItem struct {
	Number int    `json:"number"`
	Title  string `json:"title"`
	Labels []struct {
		Name string `json:"name"`
	} `json:"labels"`
}

func runGHList(ctx context.Context, kind string, args ...string) ([]ghItem, error) {
	full := append([]string{kind, "list"}, args...)
	cmd := exec.CommandContext(ctx, "gh", full...)
	out, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	var items []ghItem
	if err := json.Unmarshal(out, &items); err != nil {
		return nil, fmt.Errorf("decode gh output: %w", err)
	}
	return items, nil
}

func labelSuffix(labels []struct {
	Name string `json:"name"`
}) string {
	if len(labels) == 0 {
		return ""
	}
	names := make([]string, 0, len(labels))
	for _, l := range labels {
		names = append(names, l.Name)
	}
	return " [" + strings.Join(names, ", ") + "]"
}

func gatherCheckpoints(ctx context.Context, limit int) string {
	checkpoints, err := strategy.ListCheckpoints(ctx)
	if err != nil {
		return skip("could not list checkpoints: " + oneLine(err.Error()))
	}
	if len(checkpoints) == 0 {
		return skip("no committed checkpoints in this repo yet")
	}

	fileCount := map[string]int{}
	agentCount := map[string]int{}
	var newest, oldest time.Time
	for _, c := range checkpoints {
		for _, f := range c.FilesTouched {
			fileCount[f]++
		}
		if a := strings.TrimSpace(string(c.Agent)); a != "" {
			agentCount[a]++
		}
		if newest.IsZero() || c.CreatedAt.After(newest) {
			newest = c.CreatedAt
		}
		if oldest.IsZero() || c.CreatedAt.Before(oldest) {
			oldest = c.CreatedAt
		}
	}

	var b strings.Builder
	fmt.Fprintf(&b, "- %d committed checkpoints", len(checkpoints))
	if !newest.IsZero() {
		fmt.Fprintf(&b, " (%s to %s)", oldest.Format("2006-01-02"), newest.Format("2006-01-02"))
	}
	b.WriteString("\n")
	if len(agentCount) > 0 {
		fmt.Fprintf(&b, "- Agents: %s\n", joinCounts(agentCount, 5))
	}
	if len(fileCount) > 0 {
		b.WriteString("- Most frequently changed files (churn hotspots):\n")
		for _, fc := range topCounts(fileCount, tuneTopFiles) {
			fmt.Fprintf(&b, "  - %s (%d)\n", fc.key, fc.n)
		}
	}
	_ = limit // checkpoint listing is already bounded by repo history
	return b.String()
}

func gatherTrails(ctx context.Context, errW io.Writer, limit int) string {
	var out strings.Builder
	err := runAuthenticatedDataAPI(ctx, errW, false, func(ctx context.Context, client *api.Client) error {
		forge, owner, repo, err := resolveTrailRemote(ctx)
		if err != nil {
			return err
		}
		resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo)+trailListQuery(nil, "", limit))
		if err != nil {
			return err
		}
		defer resp.Body.Close()
		if err := checkTrailResponse(resp); err != nil {
			return err
		}
		var list api.TrailListResponse
		if err := api.DecodeJSON(resp, &list); err != nil {
			return err
		}
		if len(list.Trails) == 0 {
			out.WriteString("Trails are enabled but none exist yet.\n")
			return nil
		}
		fmt.Fprintf(&out, "- %d recent trails\n", len(list.Trails))

		sevCount := map[string]int{}
		statusCount := map[string]int{}
		fileCount := map[string]int{}
		total := 0
		scanned := list.Trails
		if len(scanned) > tuneMaxTrails_Findings {
			scanned = scanned[:tuneMaxTrails_Findings]
		}
		for i := range scanned {
			comments, err := fetchAllTrailReviewComments(ctx, client, scanned[i].ID, trailReviewSummaryOptions())
			if err != nil {
				continue
			}
			for _, c := range comments {
				total++
				if c.Severity != nil {
					sevCount[*c.Severity]++
				}
				statusCount[c.Status]++
				if c.Location.FilePath != nil {
					fileCount[*c.Location.FilePath]++
				}
			}
		}
		if total == 0 {
			out.WriteString("- No past review findings recorded.\n")
			return nil
		}
		fmt.Fprintf(&out, "- %d past review findings across %d trails\n", total, len(scanned))
		if len(sevCount) > 0 {
			fmt.Fprintf(&out, "  - by severity: %s\n", joinCounts(sevCount, 5))
		}
		if len(statusCount) > 0 {
			// resolved/dismissed/stale findings are a calibration signal:
			// dismissed or stale findings hint the eval over-fired.
			fmt.Fprintf(&out, "  - by status: %s\n", joinCounts(statusCount, 6))
		}
		if len(fileCount) > 0 {
			out.WriteString("  - files most flagged:\n")
			for _, fc := range topCounts(fileCount, 10) {
				fmt.Fprintf(&out, "    - %s (%d)\n", fc.key, fc.n)
			}
		}
		return nil
	})
	if err != nil {
		return skip("trails unavailable: " + oneLine(err.Error()))
	}
	return out.String()
}

type keyCount struct {
	key string
	n   int
}

func topCounts(m map[string]int, n int) []keyCount {
	out := make([]keyCount, 0, len(m))
	for k, v := range m {
		out = append(out, keyCount{k, v})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].n != out[j].n {
			return out[i].n > out[j].n
		}
		return out[i].key < out[j].key
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}

func joinCounts(m map[string]int, n int) string {
	parts := make([]string, 0, n)
	for _, fc := range topCounts(m, n) {
		parts = append(parts, fmt.Sprintf("%s=%d", fc.key, fc.n))
	}
	return strings.Join(parts, ", ")
}

func oneLine(s string) string {
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.TrimSpace(s)
	if len(s) > 200 {
		s = s[:200] + "…"
	}
	return s
}

func itoa(n int) string { return fmt.Sprintf("%d", n) }

