// a {{placeholder}} present in the original. The backend substitutes those
// placeholders at run time, so a dropped one silently breaks the runner — and
// the model is only *asked* to preserve them, not forced to.
func validateNewTemplate(oldTemplate, newTemplate string) error {
	if strings.TrimSpace(newTemplate) == "" {
		return errors.New("rewritten template is empty")
	}
	have := make(map[string]bool)
	for _, ph := range placeholderRe.FindAllString(newTemplate, -1) {
		have[ph] = true
	}
	var missing []string
	seen := make(map[string]bool)
	for _, ph := range placeholderRe.FindAllString(oldTemplate, -1) {
		if seen[ph] {
			continue
		}
		seen[ph] = true
		if !have[ph] {
			missing = append(missing, ph)
		}
	}
	if len(missing) > 0 {
		return fmt.Errorf("rewritten template dropped placeholder(s): %s", strings.Join(missing, ", "))
	}
	return nil
}

